    sourceRoot: host.sourceRoot, stateRoot: host.stateRoot, environmentFile: host.environmentFile,
    inputs: [host.planFile, ...(host.inputFiles ?? []).map(item => item.path)],
    allowLoopback: allowLoopback === true,
